import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(matrix):
        rows, cols = len(matrix), len(matrix[0])
        for i in range(rows):
            max_row = i + max(range(i, rows), key=lambda x: abs(matrix[x][i]))
            matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
            factor = 1 / matrix[i][i]
            for j in range(cols):
                matrix[i][j] *= factor
            for k in range(rows):
                if k != i:
                    factor = matrix[k][i]
                    for j in range(cols):
                        matrix[k][j] -= factor * matrix[i][j]
        return matrix

    def hodge_index(matrix):
        rows, cols = len(matrix), len(matrix[0])
        det = 1
        for i in range(min(rows, cols)):
            det *= matrix[i][i]
        if det == 0:
            return None
        return abs(det)

    n = random.randint(5, 40)
    X = set(range(n))
    Y = set(range(n))
    M = [[0] * len(Y) for _ in range(len(X))]

    for x in X:
        for y in Y:
            if random.choice([True, False]):
                M[x][y] = 1

    H_M = hodge_index(gaussian_elimination(M))

    if H_M is None or H_M < n ** (1/2):
        return {
            "metric_name": "H(M)",
            "metric_value": H_M,
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": "H(M) < n^(1/2)"
        }

    return {
        "metric_name": "H(M)",
        "metric_value": H_M,
        "instances_tested": 1,
        "conjecture_holds": True,
        "counterexample": ""
    }

